// spec: .qa/e2e/specs/guided-prayer.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { startNearestPrayer } from '../_helpers/prayer-start';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

async function counterText(page: Page) {
  const body = await page.locator('body').innerText();
  return (body.match(/\d+ מתוך \d+/) ?? [''])[0];
}

test.describe('Молитва по шагам', () => {
  test('GP-01 Молитва: шапка, «X מתוך Y», המשך/קודם, выход и возврат на тот же חלק #6a86f7e9 @prod-safe', async ({ page }) => {
    // 1. Сохранить `localStorage['prayer-progress']`.
    await page.goto('/home');
    await expect(page.getByRole('button', { name: 'התחל תפילה' })).toBeVisible({ timeout: 20_000 });
    const saved = await page.evaluate(() => localStorage.getItem('prayer-progress'));
    try {
      // 2. Открыть `/home` → «התחל תפילה» → `/prayer/mincha_ashkenaz` (если ближайшая молитва другая — открыть напрямую).
      // Вне окна молитвы кнопка неактивна (норма): хелпер проверяет disabled + «מתחילה ב-…» и открывает молитву напрямую.
      await startNearestPrayer(page);
      await expect(page).toHaveURL(/\/prayer\//);
      if (!/\/prayer\/mincha_ashkenaz$/.test(page.url())) {
        await page.goto('/prayer/mincha_ashkenaz');
      }
      await expect(page.getByRole('heading', { level: 1, name: 'מנחה (אשכנזי)' })).toBeVisible();
      await expect(page.getByText(/\d+ מתוך \d+/).first()).toBeVisible();
      // Часть: заголовок и текст с никудом.
      await expect(page.getByText(/[ְ-ׇ]/).first()).toBeVisible();

      // 3. Запомнить «N מתוך M». «המשך» → N+1; «קודם» → N; «המשך» → N+1.
      const m = (await counterText(page)).match(/(\d+) מתוך (\d+)/)!;
      const n = Number(m[1]);
      const total = Number(m[2]);
      // Чтобы «המשך» был доступен как переход, берём позицию не последней.
      if (n >= total) {
        await page.getByText('קודם', { exact: true }).click();
      }
      const base = Number((await counterText(page)).match(/(\d+) מתוך/)![1]);
      await page.getByText('המשך', { exact: true }).click();
      await expect(page.getByText(`${base + 1} מתוך ${total}`)).toBeVisible();
      await page.getByText('קודם', { exact: true }).click();
      await expect(page.getByText(`${base} מתוך ${total}`)).toBeVisible();
      await page.getByText('המשך', { exact: true }).click();
      await expect(page.getByText(`${base + 1} מתוך ${total}`)).toBeVisible();
      // «סיים תפילה» видна и активна — НЕ нажимать.
      const finish = page.getByRole('button', { name: 'סיים תפילה' });
      await expect(finish).toBeVisible();
      await expect(finish).toBeEnabled();

      // 4. «חזרה» → `/home`; снова открыть `/prayer/mincha_ashkenaz` — та же часть.
      await page.getByRole('button', { name: 'חזרה' }).click();
      await expect(page).toHaveURL(/\/home$/);
      await page.goto('/prayer/mincha_ashkenaz');
      await expect(page.getByText(`${base + 1} מתוך ${total}`)).toBeVisible();
    } finally {
      // 5. Уборка: вернуть сохранённое значение `prayer-progress`.
      await page.goto('/home');
      await page.evaluate((v) => {
        if (v === null) localStorage.removeItem('prayer-progress');
        else localStorage.setItem('prayer-progress', v);
      }, saved);
    }
  });
});
